"""Explain cast argument lists, compile-time branches, hashes and instrumentation."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1585': ('주소 앞에 자료형 표시를 붙인 이름표를 만든다고 생각해 보세요. 생성기는 그 위치에 든 숫자를 읽는 대신, 나중에 쓸 C 글자를 이어 붙여요.', 'cast와 인자 이름을 합쳐 두 구성의 호출 목록을 만드는 과정을 이해합니다.', 'v p:old i:new에서 32비트 쪽 “v, (int *)old, new”와 64비트 쪽 “v, (s64 *)old, new”를 적으세요.', ['gen_args_cast는 C 함수 호출의 인자 목록을 만드는 쉘 함수예요. 처음 두 입력은 기본 정수 이름과 원자 계열 이름이에요. 나머지는 v·p:old·i:new 같은 인자 명세예요.', '각 항목에서 gen_cast로 필요한 자료형 표시를 얻고 gen_param_name으로 이름을 얻어요. $(...)는 명령이 출력한 글자를 가져오는 쉘 문법이에요. 여기서는 실제 counter의 숫자를 가져오지 않아요.', 'p:old에 기본 정수 s64를 적용하면 cast는 (s64 *), 이름은 old예요. 둘을 붙여 (s64 *)old를 출력해요. i:new는 이 도우미의 cast 대상이 아니므로 이름 new만 나와요.', 'v p:old i:new를 int·atomic과 함께 처리하면 v, (int *)old, new가 나와요. s64·atomic64와 함께 처리하면 v, (s64 *)old, new가 나와요. 같은 명세에서 타입 선택만 달리한 결과예요.', '반복문은 항목 사이에만 쉼표를 붙이고 shift로 다음 항목으로 넘어가요. 같은 원천 목록을 사용하므로 두 구성에서 인자 이름과 순서를 맞추기 쉬워요. 서로 무관한 두 목록을 손으로 따로 쓰는 방식이 아니에요.', '선언 목록은 atomic_long_t *v처럼 타입과 이름을 적고, 호출 목록은 v처럼 전달할 표현을 적어요. 이 생성기는 필요한 포인터에만 cast 표현을 더해요. 실제 값 전달과 원자 갱신은 생성된 C가 컴파일되어 호출될 때 일어나요.'], [('p:old의 cast 글자를 만든 뒤 무엇을 붙이나요?', ['그 순간 counter 안에 든 숫자를 붙여요', '인자 이름 old를 붙여요'], '정답은 두 번째예요. (s64 *)와 old를 붙여 (s64 *)old라는 C 표현을 만들어요. 생성 시점에 실제 counter 값을 읽는 과정이 아니에요.'), ('32비트와 64비트 쪽 목록은 서로 다른 원천 명세를 손으로 관리하나요?', ['아니요. 같은 목록에 int·atomic 또는 s64·atomic64를 적용해요', '네. 이름과 순서도 무관한 두 목록이에요'], '정답은 첫 번째예요. 명세는 같고 타입 설정이 달라요. 그러므로 old 앞 cast는 달라도 v, old, new라는 인자 순서는 함께 유지돼요.')]), 'os1586': ('설계도에 두 가지 기계용 부품 목록을 적어 두고, 만들 때 알맞은 쪽을 고를 수 있어요. 생성된 C의 CONFIG 분기도 그런 선택을 담고 있어요.', '코드 생성·전처리·실행 단계와 생성 경로 주석을 구별합니다.', '표 한 행 → 문서 → C 선언 → CONFIG_64BIT 두 갈래 → 컴파일할 갈래 선택 → 나중 호출의 순서를 그리세요.', ['gen_proto_order_variant는 meta와 이름 조각, 순서 이름, 인자 명세를 받아 함수 하나의 글자를 만들어요. 반환 타입과 선언 목록, 32비트·64비트 쪽 호출 목록을 먼저 준비해요.', 'gen_kerneldoc으로 설명 주석을 먼저 출력하고 cat <<EOF 구간에서 C 함수 본문을 출력해요. 이렇게 여러 줄의 글을 한 덩어리로 넣는 쉘 문법을 here document라고 해요. 그 안의 ${ret} 같은 변수는 준비한 글자로 채워져요.', '출력 본문에는 #ifdef CONFIG_64BIT, #else, #endif가 있어요. CONFIG_64BIT 쪽은 raw_atomic64 계열을, 다른 쪽은 raw_atomic 계열을 호출하도록 적어요. 생성기는 두 갈래의 C 글자를 모두 만들어요.', '어느 갈래를 쓸지는 생성된 C를 컴파일하는 과정의 전처리 단계에서 설정에 따라 정해져요. 실행 중 원자 함수가 불릴 때마다 쉘이 설정을 읽고 파일을 다시 만드는 것은 아니에요.', '생성기는 표에서 영문 소문자로 시작하는 행들을 읽어 함수를 펼쳐요. 고정 헤더에는 raw_atomic_long wrapper가 85개 있어요. 개수는 생성 결과의 규모이고, 실제 원자 알고리즘의 모든 구현이 이 파일 안에 있다는 뜻은 아니에요.', '파일 앞 Generated by 주석에는 쉘의 $0, 즉 실행한 스크립트 이름·경로가 들어가요. 같은 코드를 생성해도 호출 경로 표기가 다르면 이 주석이 달라질 수 있어요. 전체 파일을 글자 그대로 비교할 때 경로도 맞춰야 하는 이유예요.'], [('생성기가 출력한 CONFIG_64BIT 두 갈래는 언제 선택되나요?', ['매번 원자 함수가 호출될 때 쉘이 선택해요', '생성된 C를 컴파일하는 과정에서 선택돼요'], '정답은 두 번째예요. #ifdef는 C 전처리 지시문이에요. 쉘의 생성 단계와 C의 전처리·컴파일·실행 단계를 나누어 보세요.'), ('생성 파일 전체를 정확히 비교할 때 스크립트 호출 경로도 고려하는 이유는 무엇인가요?', ['Generated by 주석에 $0의 경로가 들어가기 때문이에요', '그 경로가 counter를 잠그는 주소 해시가 되기 때문이에요'], '정답은 첫 번째예요. 경로는 생성 정보를 적는 주석에 쓰여요. 주석 글자의 차이와 원자 갱신의 동작을 구별해야 해요.')]), 'os1587': ('문서를 다 만든 뒤 내용으로 확인용 지문을 계산해 마지막 줄에 붙인다고 생각해 봅시다. 지문을 붙이기 전 내용과 붙인 뒤 내용은 다르므로 순서가 중요해요.', '상위 생성 절차와 해시 계산의 입력 범위를 이해합니다.', '헤더 본문 생성 → 본문의 SHA-1 계산 → 해시 문자열 추출 → // 해시 줄 추가를 네 칸으로 그리세요.', ['gen-atomics.sh는 여러 생성 작업을 차례로 연결하는 상위 쉘 스크립트예요. 계측용, long용, 아키텍처 대체 구현용 생성기와 각각의 출력 헤더를 목록으로 정해요.', '반복문은 목록에서 스크립트와 헤더 이름을 읽고 생성기를 실행해 해당 파일에 결과를 써요. >는 출력을 파일에 쓰는 기호예요. 이 스크립트를 실제 원문 위치에서 실행하면 헤더를 다시 쓰므로 학습 재현은 임시 복사에서 해야 해요.', '그다음 sha1sum으로 방금 만든 헤더 내용의 SHA-1 해시를 계산해요. 해시는 내용을 바탕으로 만든 짧은 확인 문자열이에요. 같다는 사실만으로 보안이나 모든 의미가 증명되는 것은 아니며, 정확한 재현에는 본문 비교도 할 수 있어요.', 'HASH에서 공백 뒤 파일 이름 부분을 떼어 해시 문자열만 남겨요. 이후 printf와 >>로 // 해시 형태의 마지막 줄을 덧붙여요. >>는 기존 내용 뒤에 추가하는 기호예요.', '해시 입력은 자기 해시 줄을 붙이기 전의 본문이에요. 해시를 붙인 뒤 그 전체를 다시 계산하는 무한 반복이 아니에요. 확인할 때도 마지막 줄을 제외한 같은 범위로 계산해야 해요.', 'long 헤더 하나를 재생성해 일치 여부를 확인했다고 나머지 두 생성기도 실행한 것은 아니에요. 파일 일치는 그 산출물 재현의 증거예요. 모든 원자 연산의 동시 실행이나 성능까지 올바르다는 증명으로 넓히면 안 돼요.'], [('마지막 해시 줄을 만들 때 어떤 내용을 입력으로 계산하나요?', ['이미 자기 해시 줄이 든 전체 파일을 끝없이 다시 계산해요', '해시 줄을 덧붙이기 전의 헤더 본문을 계산해요'], '정답은 두 번째예요. 본문 출력, sha1sum, 마지막 줄 추가 순서예요. 확인할 때도 입력 범위를 같게 해야 해요.'), ('long 헤더 하나를 재생성해 비교했다면 세 생성기를 모두 실행한 증거인가요?', ['아니요. 확인한 long 경로의 재생성 증거예요', '네. 하나가 같으면 나머지 생성기도 실행한 것으로 봐요'], '정답은 첫 번째예요. 상위 목록에 세 작업이 있다는 사실과 실제 세 작업을 모두 실행한 사실은 달라요. 검사 범위에 맞게 결과를 말해야 해요.')]), 'os1588': ('운동 기록원이 선수가 움직였다고 기록하는 일과 선수가 실제로 움직이는 일은 달라요. 계측 함수는 접근을 분석 도구에 알리고, 원자 연산은 따로 수행해요.', '접근 보고 hook과 실제 raw 원자 연산의 역할을 구별합니다.', '일반 atomic 함수 → 접근 보고 hook → raw 원자 함수 → 결과 반환의 네 칸을 그리세요.', ['계측은 프로그램의 동작을 살펴볼 수 있게 검사 지점을 넣는 일이에요. hook은 특정 시점에 연결해 부르는 함수나 처리 지점이에요. 여기서는 메모리에 어떤 접근을 하는지 알리는 역할과 연결돼요.', '생성기는 일반 atomic wrapper를 만들 때 checks라는 검사 코드와 raw 호출을 별도로 준비해요. 함수 본문에는 checks가 먼저 나오고 다음에 raw 함수를 호출해요. 값을 반환하는 함수라면 raw가 준 결과를 반환해요.', '예를 들어 일반 읽기에서 접근 주소와 크기를 알린 뒤 raw 읽기를 할 수 있어요. 보고만 했다고 counter를 더하거나 바꾼 것은 아니에요. 실제 원자 연산의 계산은 그 뒤의 raw 경로가 담당해요.', 'KASAN은 잘못된 메모리 접근을 찾는 데, KCSAN은 동시에 같은 자료에 접근하는 문제를 찾는 데 사용하는 커널 분석 기능이에요. 계측 지점은 이런 기능이 접근을 살펴볼 수 있게 연결해요. 실제 동작은 설정과 분석 기능에 따라 달라져요.', '계측을 피해야 하는 특별한 noinstr 영역에서는 raw 계열을 쓰라는 안내가 있어요. 일반 코드에서는 원문이 권하는 일반 API를 사용해요. 접근 보고 hook 자체를 자물쇠나 모든 CPU의 순서를 보장하는 장벽으로 생각하면 안 돼요.', '연습용 모델에서 hook 호출 기록이 맞았다고 실제 KCSAN이 경쟁 문제를 탐지했다고 말할 수는 없어요. 보고 연결의 확인과 실제 분석 엔진의 실행은 다른 검사예요. 모든 경쟁을 찾아냈다는 주장까지 넓히지 마세요.'], [('접근 보고 hook이 raw 함수를 대신해서 counter 갱신까지 하나요?', ['네. hook을 부르면 counter 계산도 자동으로 끝나요', '아니요. 보고 코드 뒤에 실제 raw 원자 함수를 호출해요'], '정답은 두 번째예요. 생성 본문은 checks와 raw 호출을 따로 출력해요. 분석 도구에 알리는 일과 실제 숫자를 바꾸는 일은 역할이 달라요.'), ('모델에서 hook 기록 검사가 통과하면 실제 KCSAN 경쟁 탐지도 성공한 것인가요?', ['아니요. 모델의 보고 흐름 확인과 실제 탐지 실행은 달라요', '네. 그 기록만으로 커널의 모든 경쟁을 탐지했어요'], '정답은 첫 번째예요. hook이 불렸다는 기록은 연결 확인에 도움이 되지만 분석 엔진이 실제 문제를 찾아낸 증거를 대신하지는 못해요.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_392.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
